"""Shared helpers for the docs generators (``scripts/gen_*.py``).

A generated region sits between two HTML comments in a hand-written page:

    <!-- BEGIN GENERATED by scripts/gen_x.py -->
    ...
    <!-- END GENERATED -->

``replace_generated`` rewrites only that region, so the prose around it stays editable.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

__all__ = ["banner", "replace_generated", "write_if_changed"]

_END = "<!-- END GENERATED -->"


def banner(script: str, source: str | None = None, *, title: str = "Generated section") -> str:
    """The admonition at the top of every generated region or file."""
    origin = f" from `{source}`" if source else ""
    return (
        f'!!! info "{title}"\n'
        f"    Generated by `{script}`{origin}. Do not edit it by hand: change the source,\n"
        f"    then run `uv run python scripts/gen_docs.py`.\n"
    )


def replace_generated(page: Path, body: str, *, script: str, check: bool = False) -> int:
    """Replace the generated region of ``page`` with ``body``. Returns a process exit code."""
    begin = f"<!-- BEGIN GENERATED by {script} -->"
    text = page.read_text(encoding="utf-8")
    pattern = re.compile(re.escape(begin) + r".*?" + re.escape(_END), re.DOTALL)
    if not pattern.search(text):
        print(f"{page}: missing the markers {begin!r} … {_END!r}", file=sys.stderr)
        return 2
    region = f"{begin}\n\n{banner(script)}\n{body.rstrip()}\n\n{_END}"
    updated = pattern.sub(lambda _: region, text, count=1)
    return write_if_changed(page, updated, check=check)


def write_if_changed(path: Path, content: str, *, check: bool = False) -> int:
    current = path.read_text(encoding="utf-8") if path.exists() else None
    if current == content:
        return 0
    if check:
        print(f"stale: {path} (run `uv run python scripts/gen_docs.py`)", file=sys.stderr)
        return 1
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    print(f"wrote {path}")
    return 0
